    "culturalNoteBn": "মেজবান হল একটি বিশাল চট্টগ্রামের জনগোষ্ঠীর ভোজ যা শতাব্দীর পূর্বের, যেখানে হাজার হাজার লোককে এই স্বাক্ষরিত গরুর মাংসের তরকারি পরিবেশন করা হয়।"
