    "descriptionBn": "একটি মাটির পাত্রের (কুন্না) ভিতরে প্রস্তুত একটি ঘন, সমৃদ্ধ গ্রেভিতে ধীরে ধীরে রান্না করা মাটন শঙ্ক।",
